<?php
declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$msg='';$settings=$db->query('SELECT * FROM crm_automation_settings WHERE id=1')->fetch();if($_SERVER['REQUEST_METHOD']==='POST'){$enabled=isset($_POST['enabled'])?1:0;$auto=isset($_POST['auto_score'])?1:0;$rh=max(1,(int)($_POST['reminder_hours']??24));$ih=max(1,(int)($_POST['initial_followup_hours']??24));$pd=max(1,(int)($_POST['proposal_followup_days']??3));$nr=max(1,(int)($_POST['no_response_days']??5));$db->prepare('UPDATE crm_automation_settings SET enabled=?,auto_score=?,reminder_hours=?,initial_followup_hours=?,proposal_followup_days=?,no_response_days=? WHERE id=1')->execute([$enabled,$auto,$rh,$ih,$pd,$nr]);$settings=$db->query('SELECT * FROM crm_automation_settings WHERE id=1')->fetch();$msg='Automation settings saved.';}$stats=$db->query("SELECT SUM(status='pending') pending,SUM(status='sent') sent,SUM(status='failed') failed,SUM(status='pending' AND COALESCE(next_attempt_at,scheduled_at)<=NOW()) due FROM lead_followups")->fetch()?:[];$pending=$db->query("SELECT f.*,l.name,l.email,l.service,l.status FROM lead_followups f JOIN leads l ON l.id=f.lead_id WHERE f.status='pending' ORDER BY COALESCE(f.next_attempt_at,f.scheduled_at) ASC LIMIT 50")->fetchAll();$failed=$db->query("SELECT f.*,l.name,l.email,l.service FROM lead_followups f JOIN leads l ON l.id=f.lead_id WHERE f.status='failed' ORDER BY f.last_attempt_at DESC LIMIT 25")->fetchAll();$logs=$db->query('SELECT a.*,l.name FROM automation_logs a LEFT JOIN leads l ON l.id=a.lead_id ORDER BY a.created_at DESC LIMIT 30')->fetchAll();$esc=static fn($v):string=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$dt=static fn($v):string=>$v?date('d M Y, H:i',strtotime((string)$v)):'—';?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CRM Automation</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:1200px"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2">CRM Automation</h1><p class="text-muted">Lead scoring, scheduled follow-ups, retries and automated email delivery</p></div><div><a href="communications.php" class="btn btn-outline-dark">Communications</a><a href="crm-dashboard.php" class="btn btn-dark ms-2">CRM Dashboard</a></div></div><?php if($msg):?><div class="alert alert-success"><?=$esc($msg)?></div><?php endif;?><div class="row g-3 mb-4"><div class="col-md-3"><div class="card border-0 shadow-sm p-3"><small class="text-muted">Pending</small><div class="h3 mb-0"><?=number_format((int)($stats['pending']??0))?></div></div></div><div class="col-md-3"><div class="card border-0 shadow-sm p-3"><small class="text-muted">Due now</small><div class="h3 mb-0 text-danger"><?=number_format((int)($stats['due']??0))?></div></div></div><div class="col-md-3"><div class="card border-0 shadow-sm p-3"><small class="text-muted">Sent</small><div class="h3 mb-0 text-success"><?=number_format((int)($stats['sent']??0))?></div></div></div><div class="col-md-3"><div class="card border-0 shadow-sm p-3"><small class="text-muted">Failed</small><div class="h3 mb-0 text-danger"><?=number_format((int)($stats['failed']??0))?></div></div></div></div><div class="row g-4"><div class="col-lg-4"><div class="card border-0 shadow-sm p-4"><h2 class="h5">Automation Settings</h2><form method="post"><div class="form-check form-switch mb-3"><input class="form-check-input" type="checkbox" name="enabled" id="enabled" <?=$settings['enabled']?'checked':''?>><label class="form-check-label" for="enabled">Enable automation</label></div><div class="form-check form-switch mb-3"><input class="form-check-input" type="checkbox" name="auto_score" id="auto_score" <?=$settings['auto_score']?'checked':''?>><label class="form-check-label" for="auto_score">Automatic lead scoring</label></div><label class="form-label">Admin reminder hours</label><input type="number" min="1" name="reminder_hours" class="form-control mb-3" value="<?=$esc($settings['reminder_hours'])?>"><label class="form-label">Initial follow-up hours</label><input type="number" min="1" name="initial_followup_hours" class="form-control mb-3" value="<?=$esc($settings['initial_followup_hours'])?>"><label class="form-label">Proposal follow-up days</label><input type="number" min="1" name="proposal_followup_days" class="form-control mb-3" value="<?=$esc($settings['proposal_followup_days'])?>"><label class="form-label">No-response days</label><input type="number" min="1" name="no_response_days" class="form-control mb-3" value="<?=$esc($settings['no_response_days'])?>"><button class="btn btn-dark w-100">Save Settings</button></form></div></div><div class="col-lg-8"><div class="card border-0 shadow-sm p-4 mb-4"><div class="d-flex justify-content-between"><h2 class="h5">Follow-up Queue</h2><span class="badge text-bg-dark"><?=count($pending)?></span></div><div class="table-responsive"><table class="table table-sm align-middle"><thead><tr><th>Lead</th><th>Type</th><th>Next attempt</th><th>Attempts</th><th>Status</th></tr></thead><tbody><?php foreach($pending as $f):$next=$f['next_attempt_at']?:$f['scheduled_at'];?><tr><td><strong><?=$esc($f['name'])?></strong><div class="small text-muted"><?=$esc($f['email'])?></div></td><td><?=ucfirst(str_replace('_',' ',$esc($f['followup_type'])))?></td><td class="<?=strtotime($next)<=time()?'text-danger fw-bold':''?>"><?=$esc($dt($next))?></td><td><?=$esc($f['attempt_count'])?> / 3</td><td><span class="badge text-bg-warning">Pending</span></td></tr><?php endforeach;?><?php if(!$pending):?><tr><td colspan="5" class="text-muted">No pending automated follow-ups.</td></tr><?php endif;?></tbody></table></div></div><div class="card border-0 shadow-sm p-4 mb-4"><h2 class="h5">Failed Follow-ups</h2><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Lead</th><th>Attempts</th><th>Last Attempt</th><th>Error</th></tr></thead><tbody><?php foreach($failed as $f):?><tr><td><?=$esc($f['name'])?></td><td><?=$esc($f['attempt_count'])?></td><td><?=$esc($dt($f['last_attempt_at']))?></td><td class="small text-danger"><?=$esc($f['error_message'])?></td></tr><?php endforeach;?><?php if(!$failed):?><tr><td colspan="4" class="text-muted">No failed follow-ups.</td></tr><?php endif;?></tbody></table></div></div><div class="card border-0 shadow-sm p-4"><h2 class="h5">Automation Log</h2><?php foreach($logs as $l):?><div class="border-bottom py-2"><div class="d-flex justify-content-between"><strong><?=$esc($l['event_type'])?></strong><small class="text-muted"><?=$esc($dt($l['created_at']))?></small></div><div class="small text-secondary"><?=$esc($l['message'])?></div></div><?php endforeach;?><?php if(!$logs):?><p class="text-muted">No automation events yet.</p><?php endif;?></div></div></div></main></body></html>